import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    targets = features[:2].abs() + 1.0
    return {"inputs": synth.Tensor(features), "depths": synth.Tensor(targets)}
dataset = synth.Spec("si-log-depth", generator=samples, size=16, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class LogDepthModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        return {"log_depth": self.network(inputs)}
model = LogDepthModel()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "si-log", "loss_kwargs": {"lambda_": 0.5}, "bindings": {"logits_or_prediction": {"output": "log_depth"}, "targets": {"batch": "depths"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
